/**
 * The one shared Supabase client.
 *
 * ES modules are evaluated once and then cached, so every file that
 * imports `supabase` from here receives the very same object. That gives
 * us a singleton without writing any singleton code.
 *
 * The library is loaded straight from a CDN as an ES module, which is
 * what lets this project run with no bundler and no build step for the
 * JavaScript itself.
 */
import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
// config.js is generated by scripts/build-config.mjs from environment variables.
import { SUPABASE_URL, SUPABASE_ANON_KEY } from '../config.js';

/** False until the two values are filled in; app.js shows setup help in that case. */
export const isConfigured = Boolean(SUPABASE_URL && SUPABASE_ANON_KEY);

/**
 * The anon key is meant to be public. It only identifies the project;
 * what a visitor may actually do is decided by the Row Level Security
 * policies in supabase/schema.sql. Never put the service_role key here.
 */
export const supabase = isConfigured
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      auth: {
        persistSession: true, // keep the login in localStorage across reloads
        autoRefreshToken: true, // swap the short-lived token before it expires
      },
    })
  : null;

/**
 * Supabase calls do not throw. They resolve to { data, error }.
 * This helper converts that shape into normal JavaScript: return the
 * data or throw, so callers can use plain try/catch.
 *
 *   const rows = unwrap(await supabase.from('profiles').select());
 */
export function unwrap({ data, error }) {
  if (error) throw new Error(error.message);
  return data;
}
